using System;using System.IO;using System.Drawing;using System.Runtime.InteropServices;using System.Windows;using System.Windows.Controls;using System.Windows.Controls.Primitives;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Interop;using DualSteam.UI;using Forms=System.Windows.Forms;
public sealed class ManagerTray:IDisposable {
 readonly Forms.NotifyIcon manager,second;readonly Icon mainIcon,secondIcon;readonly ContextMenu menu;readonly MenuItem quitItem;readonly TextBlock status;bool disposed;
 [DllImport("user32")]static extern bool SetForegroundWindow(IntPtr hwnd);
 static Icon Load(string path){using(var stream=new MemoryStream(File.ReadAllBytes(path)))using(var icon=new Icon(stream))return (Icon)icon.Clone();}
 public ManagerTray(Action show,Action open,Action quit,Action exit):this(show,open,quit,exit,show,show,show,show){}
 public ManagerTray(Action show,Action open,Action quit,Action exit,Action main,Action settings,Action updates,Action files){
  mainIcon=Load(Path.Combine(Engine.Home,@"Assets\dual-steam.ico"));secondIcon=Load(Path.Combine(Engine.Home,@"Assets\second-steam.ico"));manager=new Forms.NotifyIcon{Icon=mainIcon,Text="Dual Steam",Visible=true};second=new Forms.NotifyIcon{Icon=secondIcon,Text="Second Steam"};
  menu=new ContextMenu{MinWidth=284,Padding=new Thickness(6),BorderThickness=new Thickness(1),HasDropShadow=true,Placement=PlacementMode.MousePoint};Theme.Bind(menu,Control.BackgroundProperty,"bg.surface");Theme.Bind(menu,Control.ForegroundProperty,"text.primary");Theme.Bind(menu,Control.BorderBrushProperty,"border.sidebar");Theme.Bind(menu,Control.FontFamilyProperty,"Font.App");
  var frame=new FrameworkElementFactory(typeof(Border));frame.SetValue(Border.CornerRadiusProperty,new CornerRadius(10));frame.SetValue(Border.PaddingProperty,new Thickness(6));frame.SetValue(Border.BorderThicknessProperty,new Thickness(1));frame.SetResourceReference(Border.BackgroundProperty,"bg.surface");frame.SetResourceReference(Border.BorderBrushProperty,"border.menu");var host=new FrameworkElementFactory(typeof(StackPanel));host.SetValue(Panel.IsItemsHostProperty,true);frame.AppendChild(host);menu.Template=new ControlTemplate(typeof(ContextMenu)){VisualTree=frame};
  var title=new StackPanel{Margin=new Thickness(12,8,12,10)};title.Children.Add(Ui.Text("Dual Steam",14,"text.primary",true));status=Ui.Text("Second Steam is stopped",12,"text.muted");status.Margin=new Thickness(0,4,0,0);title.Children.Add(status);menu.Items.Add(new MenuItem{Header=title,IsEnabled=false,Focusable=false});Separator();
  Add("Open dashboard","\uE80F",show);Add("Open Main Steam","\uE7F4",main);Add("Open Second Steam","\uE8A7",open);quitItem=Add("Quit Second Steam","\uE71A",quit);quitItem.IsEnabled=false;Separator();Header("QUICK ACCESS");Add("Settings","\uE713",settings);Add("Check for updates","\uE895",updates);Add("Open app folder","\uE838",files);Separator();Add("Exit Dual Steam","\uE7E8",exit);
  menu.Opened+=(s,e)=>menu.Dispatcher.BeginInvoke(new Action(()=>{var source=PresentationSource.FromVisual(menu) as HwndSource;if(source!=null)SetForegroundWindow(source.Handle);Keyboard.Focus(menu);}));
  manager.MouseUp+=(s,e)=>{if(e.Button==Forms.MouseButtons.Right)Show();};second.MouseUp+=(s,e)=>{if(e.Button==Forms.MouseButtons.Right)Show();};manager.DoubleClick+=(s,e)=>show();second.DoubleClick+=(s,e)=>open();
 }
 void Header(string label){var text=Ui.Text(label,12,"text.muted",true);text.Margin=new Thickness(12,10,12,6);menu.Items.Add(new MenuItem{Header=text,IsEnabled=false,Focusable=false});}
 void Separator(){var line=new Separator{Margin=new Thickness(6,6,6,6)};var plate=new FrameworkElementFactory(typeof(Border));plate.SetValue(Border.HeightProperty,1.0);plate.SetResourceReference(Border.BackgroundProperty,"border.menu");line.Template=new ControlTemplate(typeof(Separator)){VisualTree=plate};menu.Items.Add(line);}
 MenuItem Add(string label,string glyph,Action action){var item=new MenuItem{Header=label,MinHeight=38,Padding=new Thickness(12,8,12,8)};Ui.Name(item,label);var row=new StackPanel{Orientation=Orientation.Horizontal};var icon=Ui.Glyph(glyph,16);icon.Width=20;icon.VerticalAlignment=VerticalAlignment.Center;row.Children.Add(icon);var text=Ui.Text(label,13);text.Margin=new Thickness(12,0,0,0);row.Children.Add(text);item.Header=row;var plate=new FrameworkElementFactory(typeof(Border));plate.Name="Plate";plate.SetValue(Border.CornerRadiusProperty,new CornerRadius(6));plate.SetValue(Border.PaddingProperty,new Thickness(12,8,12,8));plate.SetValue(Border.BackgroundProperty,System.Windows.Media.Brushes.Transparent);var content=new FrameworkElementFactory(typeof(ContentPresenter));content.SetValue(ContentPresenter.ContentSourceProperty,"Header");plate.AppendChild(content);var template=new ControlTemplate(typeof(MenuItem)){VisualTree=plate};var hover=new Trigger{Property=MenuItem.IsHighlightedProperty,Value=true};hover.Setters.Add(new Setter(Border.BackgroundProperty,new DynamicResourceExtension("bg.surfaceHover"),"Plate"));template.Triggers.Add(hover);var disabled=new Trigger{Property=UIElement.IsEnabledProperty,Value=false};disabled.Setters.Add(new Setter(UIElement.OpacityProperty,0.45));template.Triggers.Add(disabled);item.Template=template;item.Click+=(s,e)=>{menu.IsOpen=false;menu.Dispatcher.BeginInvoke(action);};menu.Items.Add(item);return item;}
 void Show(){if(disposed)return;menu.IsOpen=true;}
 public void Update(bool running,bool mainRunning=false){if(disposed)return;second.Visible=Preferences.Current.SecondTray&&running;quitItem.IsEnabled=running;status.Text=(mainRunning?"Main: running":"Main: stopped")+"   ·   "+(running?"Second: running":"Second: stopped");}
 public void Dispose(){if(disposed)return;disposed=true;menu.IsOpen=false;manager.Visible=false;second.Visible=false;manager.Dispose();second.Dispose();mainIcon.Dispose();secondIcon.Dispose();}
}